[workspace]
[package]
name = "review-mode-probe"
version = "0.0.0"
edition = "2021"

[dependencies]
blit-core = { path = "../../crates/blit-core" }
tokio = { version = "1", features = ["rt", "macros"] }
'@
[IO.File]::WriteAllText((Join-Path $modeProbe 'Cargo.toml'),$modeToml)
Copy-Item -LiteralPath (Join-Path $reviewDir 'Cargo.lock') -Destination (Join-Path $modeProbe 'Cargo.lock')
$modeCode=@'
use std::fs;
use std::os::unix::fs::{MetadataExt, PermissionsExt};
use std::path::PathBuf;

use blit_core::moved::Version;
use blit_core::remote::transfer::sink::ResumeBaseline;
use blit_core::remote::transfer::{FsSinkConfig, FsTransferSink, PreparedPayload, TransferSink};

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let root = PathBuf::from(std::env::args_os().nth(1).unwrap());
    let path = root.join("partial");
    fs::write(&path, b"original").unwrap();
    fs::set_permissions(&path, fs::Permissions::from_mode(0o644)).unwrap();
    let original = fs::metadata(&path).unwrap();
    let sink = FsTransferSink::new(root.clone(), root, FsSinkConfig {
        resume: true,
        ..FsSinkConfig::default()
    });
    sink.note_resume_baseline("partial", ResumeBaseline::Hashed(Version::of(&original)));
    sink.hold_resume_partial("partial", 4096).await.unwrap();
    let result = sink.write_payload(PreparedPayload::FileBlockComplete {
        relative_path: "partial".into(), total_size: 4096, mtime_seconds: 0,
        permissions: 0o644, windows_metadata: None,
    }).await.unwrap();
    let after = fs::metadata(&path).unwrap();
    println!("mode {:04o} -> {:04o}, size {} -> {}, bytes {:?}, failed {}",
             original.mode() & 0o7777, after.mode() & 0o7777, original.len(), after.len(),
             fs::read(&path).unwrap(), result.file_failed("partial"));
    println!("{result:?}");
}
'@
[IO.File]::WriteAllText((Join-Path $modeSrc 'main.rs'),$modeCode)
$modeLog=Join-Path $reviewRun 'mode-build.log'
cargo build --manifest-path (Join-Path $modeProbe 'Cargo.toml') *> $modeLog
if ($LASTEXITCODE -ne 0) { Get-Content -LiteralPath $modeLog -Tail 14; throw 'Probe build failed' }
